export const WORDS=[['FROG','An amphibian that often hops.'],['POND','A small body of still water.'],['SUN','The star that lights our daytime sky.'],['RAIN','Water falling from clouds.'],['TREE','A woody plant with a trunk and branches.'],['LEAF','A flat plant part that often catches sunlight.'],['REED','A tall, narrow-leaved plant often found beside water.'],['LILY','A water ___ can have floating leaves and flowers.'],['WATER','The liquid that fills a pond.'],['EGG','The first stage in the familiar frog life cycle.'],['TAIL','A tadpole has this behind its body.'],['LEGS','Body parts a frog uses to hop.'],['TADPOLE','A young stage after the egg in the familiar frog life cycle.'],['FROGLET','A young frog stage after a tadpole.'],['FLY','A small winged insect.'],['ANT','A small insect that lives in a colony.'],['MOTH','A winged insect often active at night.'],['FOREST','A habitat with many trees.'],['STREAM','A small flowing body of water.'],['MARSH','A wetland often filled with grasses and reeds.'],['MOSS','A small green plant that often grows in damp places.'],['ROCK','A solid piece of natural mineral material.'],['CLOUD','A visible mass of tiny water droplets or ice in the sky.'],['NATURE','The living world and its physical surroundings.'],['HABITAT','The place where an organism lives.'],['INSECT','A small animal with six legs as an adult.'],['NIGHT','The time between sunset and sunrise.'],['DAY','The time when your part of Earth faces the Sun.'],['MATE','A partner during reproduction.'],['SPAWN','A term often used for a mass of frog eggs.'],['ROOT','A plant part that usually grows into the soil.'],['BARK','The outer covering of a tree trunk.'],['SEED','A plant structure that can grow into a new plant.'],['SOIL','The ground material in which many plants grow.'],['FLOWER','A plant structure involved in reproduction.'],['SHORE','The land along the edge of a body of water.']];
function seeded(n){let x=n>>>0;return ()=>{x=(1664525*x+1013904223)>>>0;return x/4294967296;};}
export function createCrossword(level=1,attempt=0,wordPool=WORDS){const rng=seeded(level*7919+31+attempt*97),words=[...wordPool];for(let i=words.length-1;i>0;i--){const j=Math.floor(rng()*(i+1));[words[i],words[j]]=[words[j],words[i]];}words.sort((a,b)=>(a[3]||0)-(b[3]||0));const cells=new Map(),entries=[];const key=(r,c)=>r+','+c;const at=(r,c)=>cells.get(key(r,c));
 function candidate(word,r,c,dir,first=false){let crosses=0,fresh=0;const dr=dir==='down'?1:0,dc=dir==='across'?1:0;if(Math.abs(r)>9||Math.abs(c)>9||Math.abs(r+dr*(word.length-1))>9||Math.abs(c+dc*(word.length-1))>9)return null;if(at(r-dr,c-dc)||at(r+dr*word.length,c+dc*word.length))return null;for(let i=0;i<word.length;i++){const rr=r+dr*i,cc=c+dc*i,old=at(rr,cc);if(old){if(old.letter!==word[i]||old[dir])return null;crosses++;}else{if(dir==='across'?(at(rr-1,cc)||at(rr+1,cc)):(at(rr,cc-1)||at(rr,cc+1)))return null;fresh++;}}if(!fresh||(!first&&!crosses))return null;const all=[...cells.values(),...word.split('').map((letter,i)=>({r:r+dr*i,c:c+dc*i}))];const rows=all.map(x=>x.r),cols=all.map(x=>x.c),height=Math.max(...rows)-Math.min(...rows)+1,width=Math.max(...cols)-Math.min(...cols)+1;if(height>15||width>15)return null;return {r,c,dir,score:crosses*100-height*width};}
 function place(word,clue,pos){const dr=pos.dir==='down'?1:0,dc=pos.dir==='across'?1:0;const entry={word,clue,...pos,id:entries.length};for(let i=0;i<word.length;i++){const r=pos.r+dr*i,c=pos.c+dc*i,k=key(r,c),cell=cells.get(k)||{r,c,letter:word[i]};cell[pos.dir]=entry.id;cells.set(k,cell);}entries.push(entry);}
 const target=Math.min(12,6+Math.floor((level-1)/2));for(let pass=0;pass<3&&entries.length<target;pass++)for(const [word,clue] of words){if(entries.some(x=>x.word===word))continue;if(!entries.length){place(word,clue,{r:0,c:0,dir:'across'});continue;}let best=null;for(const old of cells.values())for(let i=0;i<word.length;i++){if(word[i]!==old.letter)continue;for(const dir of ['across','down']){const pos=candidate(word,old.r-(dir==='down'?i:0),old.c-(dir==='across'?i:0),dir);if(pos&&(!best||pos.score>best.score))best=pos;}}if(best)place(word,clue,best);if(entries.length>=target)break;}
 if(entries.length<(wordPool===WORDS?5:target)&&attempt<12)return createCrossword(level,attempt+1,wordPool);const minR=Math.min(...[...cells.values()].map(x=>x.r)),minC=Math.min(...[...cells.values()].map(x=>x.c));const normalized=new Map();for(const cell of cells.values()){cell.r-=minR;cell.c-=minC;normalized.set(key(cell.r,cell.c),cell);}entries.forEach(e=>{e.r-=minR;e.c-=minC;});const starts=[...new Set(entries.map(e=>key(e.r,e.c)))].sort((a,b)=>{const [ar,ac]=a.split(',').map(Number),[br,bc]=b.split(',').map(Number);return ar-br||ac-bc;});entries.forEach(e=>e.number=starts.indexOf(key(e.r,e.c))+1);return {level,rows:Math.max(...[...normalized.values()].map(x=>x.r))+1,cols:Math.max(...[...normalized.values()].map(x=>x.c))+1,cells:normalized,entries};}
export function checkCrossword(puzzle,letters){return puzzle.entries.map(e=>{const value=e.word.split('').map((_,i)=>letters[(e.r+(e.dir==='down'?i:0))+','+(e.c+(e.dir==='across'?i:0))]||'').join('').toUpperCase();return {id:e.id,correct:value===e.word};});}
export function crosswordState(p){p.crossword ||= {level:1,letters:{}};return p.crossword;}
export function awardCrossword(p,puzzle,letters){const state=crosswordState(p);if(state.level!==puzzle.level||!checkCrossword(puzzle,letters).every(x=>x.correct))return null;const currency=10+puzzle.entries.length*2;p.bank+=currency;state.level++;state.letters={};delete state.plan;return {currency,nextLevel:state.level};}
